mapper.sql:
WHERE (source.title LIKE CONCAT('%', #{keyword}, '%')
    OR source.content LIKE CONCAT('%', #{keyword}, '%')
    OR source.author_name LIKE CONCAT('%', #{keyword}, '%'))
AND source.document_type = #{type}
AND source.pet_type = #{petType}
AND source.category = #{category}
AND source.trust_level = #{trustLevel}
AND source.published_at >= #{publishedAfter}

mapper.select:
SELECT id, user_id, query_text, normalized_query, query_hash, filters_json,
       result_count, search_count, last_searched_at, created_at, updated_at
FROM search_history WHERE user_id = #{userId}
ORDER BY last_searched_at DESC LIMIT #{limit}

SELECT id, requested_by, index_name, index_version, status, total_count, indexed_count,
       failed_count, error_message, started_at, completed_at, created_at, updated_at
FROM search_index_job WHERE id = #{id}

mapper.update:
UPDATE search_index_job SET status = 'RUNNING', total_count = #{totalCount},
    started_at = #{startedAt}, updated_at = #{startedAt}
WHERE id = #{id} AND status = 'PENDING'

UPDATE search_index_job SET status = 'COMPLETED', indexed_count = #{indexedCount},
    failed_count = #{failedCount}, completed_at = #{completedAt}, updated_at = #{completedAt}
WHERE id = #{id} AND status = 'RUNNING'
